import { BUCKETS, type BucketType } from "./frontmatter.js";
import type { Entry } from "./scan.js";

const HEADINGS: Record<BucketType, string> = {
  user: "User",
  feedback: "Feedback",
  project: "Project",
  reference: "Reference",
};

const PREAMBLE = `# Memory Index

<!-- GENERATED by tools/brain (\`npm run index\`). Do not hand-edit — edits are overwritten. -->

Index for the auto-memory protocol. Entries are one line. Memory files live in \`memory/{user,feedback,project,reference}/\`. The session warm-cache is \`memory/hot.md\`.`;

function titleCase(slug: string): string {
  return slug
    .split("-")
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function entryLine(entry: Entry): string {
  const data = entry.data;
  const title = data?.title ?? titleCase(entry.fileSlug);
  const description = data?.description ?? "(no description)";
  return `- [${title}](${entry.rel}) — ${description}`;
}

/** Build the full MEMORY.md content from scanned entries (deterministic, sorted by name). */
export function buildIndex(entries: Entry[]): string {
  const sections: string[] = [PREAMBLE];

  for (const bucket of BUCKETS) {
    const inBucket = entries
      .filter((e) => e.bucket === bucket)
      .sort((a, b) => a.fileSlug.localeCompare(b.fileSlug));

    const lines = inBucket.map(entryLine);
    const body =
      lines.length > 0
        ? lines.join("\n")
        : `*(no entries yet — write here when relevant)*`;

    sections.push(`## ${HEADINGS[bucket]}\n${body}`);
  }

  return sections.join("\n\n") + "\n";
}
